21	// ── The demonym regression ─────────────────────────────────────────────────
22	
23	test('"french flag" returns France, not French Guiana', () => {
24	  // THE REGRESSION. Flag keywords are derived from the country NAME, so
25	  // "French Guiana" owned the literal token "french" and scored a full keyword
26	  // hit while France could only be reached through a discounted synonym. The
27	  // search returned three obscure territories and not the country anyone meant.
28	  assert.equal(findAssets("french flag", { limit: 1 })[0].id, "flag:fr");
29	});
30	
31	test('"british flag" returns the United Kingdom, not a territory', () => {
32	  assert.equal(findAssets("british flag", { limit: 1 })[0].id, "flag:gb");
33	});
34	
35	test("a sovereign country outscores or ties every territory named after it", () => {
36	  // The fix is entry-side: listing the demonym as a keyword on the country
37	  // lets it match the same token at the same strength as the territory.
38	  for (const [query, sovereign] of [
39	    ["french flag", "flag:fr"],
40	    ["british flag", "flag:gb"],
41	    ["american flag", "flag:us"],
42	  ]) {
43	    const top = findAssets(query, { kind: "flag", limit: 5 });
44	    const own = top.find((m) => m.id === sovereign);
45	    assert.ok(own, `${query} did not return ${sovereign} at all`);
46	    assert.equal(own.score, Math.max(...top.map((m) => m.score)), `${query}: ${sovereign} was outscored`);
47	  }
48	});
49	
50	test("a territory search still finds the territory", () => {
51	  // The second token is the one only the territory carries.
52	  assert.equal(findAssets("french guiana", { limit: 1 })[0].id, "flag:gf");
53	});
54	
55	test("other demonyms resolve to their country", () => {
56	  for (const [query, expected] of [
57	    ["german flag", "flag:de"],
58	    ["spanish flag", "flag:es"],
59	    ["irish flag", "flag:ie"],
60	    ["canadian flag", "flag:ca"],
61	    ["japanese flag", "flag:jp"],
62	    ["italian flag", "flag:it"],
63	  ]) {
64	    assert.equal(findAssets(query, { limit: 1 })[0].id, expected, query);
65	  }
66	});
67	
68	test("a country name and its ISO code both find it", () => {
69	  assert.equal(findAssets("france", { kind: "flag", limit: 1 })[0].id, "flag:fr");
70	  assert.equal(findAssets("united states", { kind: "flag", limit: 1 })[0].id, "flag:us");
71	  assert.equal(findAssets("usa", { kind: "flag", limit: 1 })[0].id, "flag:us");
72	});
73	
74	// ── Scoring shape ──────────────────────────────────────────────────────────
75	
76	test("an exact id beats a keyword match", () => {
77	  const results = findAssets("wrench", { kind: "icon", limit: 5 });
78	  assert.equal(results[0].id, "icon:wrench");
79	  assert.ok(results[0].score > (results[1]?.score ?? 0));
80	});
81	
82	test("a synonym hit never outranks the word the caller actually typed", () => {
83	  // "plumber" reaches the wrench only through SYNONYMS, so its score must be
84	  // strictly below what typing "wrench" scores.
85	  const literal = findAssets("wrench", { kind: "icon", limit: 1 })[0];
86	  const viaSynonym = findAssets("plumber", { kind: "icon", limit: 1 })[0];
87	  assert.equal(viaSynonym.id, "icon:wrench");
88	  assert.ok(viaSynonym.score < literal.score);
89	});
90	
91	test("business vocabulary reaches a sensible icon", () => {
92	  // The top hit must be one of the icons the trade actually maps to. Which of
93	  // them comes first is decided by an alphabetical id tie-break, not by intent
94	  // (see the "american flag" entry in tests/open-bugs.test.mjs), so pinning a
95	  // single winner here would be pinning the alphabet.
96	  for (const [query, acceptable] of [
97	    ["plumber", ["icon:wrench", "icon:droplet"]],
98	    ["electrician", ["icon:zap", "icon:wrench"]],
99	    ["barber", ["icon:scissors"]],
100	    ["dentist", ["icon:tooth"]],
101	    ["photographer", ["icon:camera"]],
102	    ["florist", ["icon:sprout", "icon:lotus", "icon:leaf"]],
103	  ]) {
104	    const top = findAssets(query, { kind: "icon", limit: 1 })[0]?.id;
105	    assert.ok(acceptable.includes(top), `${query} -> ${top}, expected one of ${acceptable.join(", ")}`);
106	  }
107	});
108	
109	test("results are sorted by descending score", () => {
110	  const scores = findAssets("coffee", { limit: 20 }).map((m) => m.score);
111	  for (let i = 1; i < scores.length; i++) assert.ok(scores[i] <= scores[i - 1]);
112	});
113	
114	test("ties break deterministically by id, so the same query never reshuffles", () => {
115	  const once = ids(findAssets("flag", { limit: 30 }));
116	  assert.deepEqual(ids(findAssets("flag", { limit: 30 })), once);
117	  assert.deepEqual(ids(findAssets("flag", { limit: 30 })), once);
118	});
119	
120	test("a query that matches nothing returns nothing, rather than guessing", () => {
121	  assert.deepEqual(findAssets("zzzzqqqq"), []);
122	  assert.deepEqual(findAssets("xylophone quantum bagpipe"), []);
123	});
124	
125	test("stopwords do not turn a real query into an empty one", () => {
126	  assert.equal(findAssets("a phone icon", { kind: "icon", limit: 1 })[0].id, "icon:phone");
127	  assert.equal(findAssets("the icons", { limit: 3 }).length, 3, "an all-stopword query lists the catalogue");
128	});
129	
130	// ── Options ────────────────────────────────────────────────────────────────
131	
132	test("limit is clamped to 1..100", () => {
133	  assert.equal(findAssets("flag", { limit: 1000 }).length, 100);
134	  assert.equal(findAssets("flag", { limit: 0 }).length, 1);
135	  assert.equal(findAssets("flag", { limit: -3 }).length, 1);
136	  assert.ok(findAssets("flag").length <= 20, "the default limit is 20");
137	});
138	
139	test("kind filters the pool", () => {
140	  for (const kind of ASSET_KINDS) {
141	    const results = findAssets("", { kind, limit: 100 });
142	    assert.ok(results.every((m) => m.kind === kind), `kind=${kind} leaked another kind`);
143	  }
144	  const two = findAssets("", { kind: ["icon", "flag"], limit: 100 });
145	  assert.ok(two.every((m) => m.kind === "icon" || m.kind === "flag"));
146	});
147	
148	test("an unrecognised kind is ignored rather than returning nothing", () => {
149	  // Better a slightly wide answer than an empty one from a typo in a tool call.
150	  assert.ok(findAssets("coffee", { kind: "nonsense", limit: 3 }).length > 0);
151	  assert.ok(findAssets("coffee", { kind: [], limit: 3 }).length > 0);
152	});
153	
154	test("an empty query lists the catalogue instead of erroring", () => {
155	  const listed = findAssets("", { limit: 5 });
156	  assert.equal(listed.length, 5);
157	  assert.ok(listed.every((m) => m.score === 0), "listed items are not scored");
158	});
159	
160	test("the icon weight option reaches the emitted source", () => {
161	  const regular = findAssets("phone", { kind: "icon", limit: 1 })[0].source;
162	  const bold = findAssets("phone", { kind: "icon", limit: 1, weight: "bold" })[0].source;
163	  assert.notEqual(regular, bold, "weight had no effect on the emitted markup");
164	});
165	
166	// ── Every match must be paste-ready and CSP-safe ───────────────────────────
167	
168	test("every match carries a non-empty source, usage and format", () => {
169	  for (const kind of ASSET_KINDS) {
170	    for (const m of listAssets(kind)) {
171	      assert.ok(m.source.length > 0, `${m.id} has an empty source`);
172	      assert.ok(m.usage.length > 0, `${m.id} has no usage line`);
173	      assert.ok(["jsx", "svg", "css", "text"].includes(m.format), `${m.id} has format ${m.format}`);
174	      assert.equal(m.kind, kind);
175	    }
176	  }
177	});
178	
179	test("no source reaches out to a remote host — the sandbox CSP would drop it", () => {
180	  // Generated sites run under default-src 'self'; img-src 'self' data:. A
181	  // hosted asset would fail silently at serve time.
182	  for (const m of listAssets()) {
183	    assert.ok(
184	      !/\b(?:src|href)\s*=\s*["']https?:/i.test(m.source),
185	      `${m.id} references a remote host: ${m.source.slice(0, 120)}`,
186	    );
187	  }
188	});
189	
190	test("jsx sources use JSX attribute spelling, not HTML", () => {
191	  for (const m of listAssets()) {
192	    if (m.format !== "jsx") continue;
193	    assert.ok(!/\sstroke-width=/.test(m.source), `${m.id} emits HTML-style stroke-width`);
194	    assert.ok(!/\sstroke-linecap=/.test(m.source), `${m.id} emits HTML-style stroke-linecap`);
195	    assert.ok(!/\sclass=/.test(m.source), `${m.id} emits class= instead of className=`);
196	  }
197	});
198	
199	// ── Catalogue plumbing ─────────────────────────────────────────────────────
200	
201	test("ids are unique and namespaced by kind", () => {
202	  const all = listAssetIds();
203	  assert.equal(new Set(all).size, all.length, "duplicate asset id");
204	  for (const id of all) assert.ok(ASSET_KINDS.includes(id.slice(0, id.indexOf(":"))), id);
205	});
206	
207	test("getAsset round-trips every id in the catalogue", () => {
208	  for (const id of listAssetIds()) assert.equal(getAsset(id)?.id, id);
209	});
210	
211	test("getAsset trims, and returns null rather than throwing on a bad id", () => {
212	  assert.equal(getAsset("  icon:phone  ")?.id, "icon:phone");
213	  assert.equal(getAsset("icon:does-not-exist"), null);
214	  assert.equal(getAsset(""), null);
215	  assert.equal(getAsset("constructor"), null);
216	  assert.equal(getAsset("__proto__"), null);
217	});
218	
219	test("the catalogue summary agrees with the catalogue", () => {
220	  const summary = assetCatalogSummary();
221	  assert.equal(summary.total, listAssetIds().length);
222	  assert.equal(
223	    summary.byKind.reduce((n, k) => n + k.count, 0),
224	    summary.total,
225	  );
226	  for (const { kind, count } of summary.byKind) assert.equal(listAssetIds(kind).length, count);
227	  assert.equal(summary.flags.withSvg + summary.flags.emojiOnly, summary.flags.total);
228	});
