5	// Bridges the asset catalogue to the SDK engine.
6	//
7	// The two engines reach assets by different routes, and that is deliberate
8	// rather than an inconsistency:
9	//
10	//  - The API engine (lib/agent.ts) has custom tools, so it gets a real
11	//    `find_assets` tool that returns matches over the wire.
12	//  - The SDK engine has a fixed toolset (Read/Write/Edit/Bash/Glob/Grep) and a
13	//    real working directory. Giving it a custom tool would mean an in-process
14	//    MCP server, whose `tool()` helper requires zod — which is only present as
15	//    a transitive dependency of the SDK, not a declared one. Depending on a
16	//    package that isn't in package.json is a silent breakage waiting for the
17	//    next install, so instead the catalogue is written to disk and the agent
18	//    uses the file tools it already has.
19	//
20	// The directory is dot-prefixed on purpose: readFileTree() in agent-sdk.ts
21	// skips any entry starting with ".", so the catalogue is invisible to the diff
22	// that turns the working directory back into project files. Rename it without
23	// the dot and every generated site gains 460-odd junk files.
24	
25	const DIR = ".kodely-assets";
26	
27	/**
28	 * Writes the catalogue into `workDir/.kodely-assets/`:
29	 *   INDEX.md          one line per asset — id, name, keywords
30	 *   <kind>/<name>.txt the paste-ready source for that asset
31	 *
32	 * Returns the number of assets written.
33	 */
34	export async function materializeAssets(workDir: string): Promise<number> {
35	  const root = path.join(workDir, DIR);
36	  // No kind filter — the whole catalogue.
37	  const all = listAssets(undefined, { limit: 1000 });
38	
39	  const byKind = new Map<string, AssetMatch[]>();
40	  for (const a of all) {
41	    const list = byKind.get(a.kind) ?? [];
42	    list.push(a);
43	    byKind.set(a.kind, list);
44	  }
45	
46	  await mkdir(root, { recursive: true });
47	
48	  const lines: string[] = [
49	    "# Kodely asset catalogue",
50	    "",
51	    "Every asset here is safe to inline — no external requests, so nothing here",
52	    "can be blocked by the published site's CSP.",
53	    "",
54	    "To use one: find its id below (Grep this file), then Read the file named on",
55	    "that line and paste its contents into the component you are writing.",
56	    "",
57	  ];
58	
59	  for (const [kind, assets] of [...byKind.entries()].sort()) {
60	    await mkdir(path.join(root, kind), { recursive: true });
61	    lines.push(`## ${kind} (${assets.length})`, "");
62	
63	    for (const a of assets) {
64	      // The id is namespaced ("icon:phone"); the bit after the colon is the
65	      // filename. Sanitised because it ends up as a real path.
66	      const leaf = a.id.split(":").slice(1).join("-").replace(/[^A-Za-z0-9._-]/g, "-") || "asset";
67	      const rel = `${DIR}/${kind}/${leaf}.txt`;
68	      await writeFile(
69	        path.join(root, kind, `${leaf}.txt`),
70	        `${a.usage}\n\n${a.source}\n`,
71	        "utf8",
72	      );
73	      lines.push(`- \`${a.id}\` — ${a.name} — ${a.keywords.slice(0, 6).join(", ")} → \`${rel}\``);
74	    }
75	    lines.push("");
76	  }
77	
78	  await writeFile(path.join(root, "INDEX.md"), lines.join("\n"), "utf8");
79	  return all.length;
80	}
81	
82	/**
83	 * Result shape for the API engine's `find_assets` tool. Trimmed to what the
84	 * model needs to paste — the full AssetMatch carries alternative encodings
85	 * that would multiply the token cost of every search for no benefit.
86	 */
87	export function formatMatchesForTool(matches: AssetMatch[]): string {
88	  if (matches.length === 0) {
89	    return "No assets matched. Try a broader term, or use a CSS gradient / inline SVG of your own.";
90	  }
91	  return matches
92	    .map((m) => [`### ${m.id} — ${m.name}`, m.usage, "", m.source].join("\n"))
93	    .join("\n\n---\n\n");
94	}
95	
96	export { findAssets };
97

      properties: { path: { type: "string", description: "Project-relative path to delete." } },
      required: ["path"],
    },
  },
  {
    name: "find_assets",
    description:
      "Search Kodely's built-in asset catalogue (icons, country flags, gradients, mesh backgrounds, grain textures, section dividers, CSS patterns, initials avatars). Returns paste-ready source for each match. Everything it returns is inlinable and CSP-safe. Prefer this over hand-writing SVG path data.",
    input_schema: {
      type: "object",
      properties: {
        query: {
          type: "string",
          description:
            "Plain-words description, e.g. 'phone icon', 'warm sunset gradient', 'wave section divider', 'french flag'.",
        },
        kind: {
          type: "string",
          enum: [...ASSET_KINDS],
          description: "Optional filter to one kind of asset.",
        },
        limit: { type: "number", description: "Max results, default 6." },
      },
      required: ["query"],
    },
  },
];

// Files the agent must never write, because they are EXECUTED server-side
// rather than merely served.
//

export function getIcon(id: string): Icon | undefined {
  return BY_ID.get(id);
}

export type IconRenderOptions = {
  /** Pixel size for width/height. Omit to emit a size-less svg sized by CSS. */
  size?: number | null;
  /** A named weight, or an explicit stroke width. Default "regular" (1.75). */
  weight?: IconWeight | number;
  /** Added to the root <svg>. */
  className?: string;
  /** Stroke colour. Defaults to currentColor so the icon inherits text colour. */
  color?: string;
  /**
   * Accessible name. When omitted the icon is emitted as aria-hidden, which is
   * the right default for an icon sitting next to a text label.
   */
  title?: string;
};

function strokeWidthOf(weight: IconRenderOptions["weight"]): number {
  if (typeof weight === "number") return weight;
  return ICON_WEIGHTS[weight ?? "regular"];
}

/**
 * A standalone `<svg>` string — paste into HTML, or into JSX after running it
 * through {@link iconJsx}.
 */
export function iconSvg(id: string, opts: IconRenderOptions = {}): string | null {
  const icon = BY_ID.get(id);
  if (!icon) return null;
  const { size = 24, className, color = "currentColor", title } = opts;
  const dims = size == null ? "" : ` width="${size}" height="${size}"`;
  const cls = className ? ` class="${className}"` : "";
  const label = title
    ? ` role="img" aria-label="${title.replace(/"/g, "&quot;")}"`
    : ` aria-hidden="true"`;
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${ICON_VIEWBOX}"${dims}` +
    ` fill="none" stroke="${color}" stroke-width="${strokeWidthOf(opts.weight)}"` +
    ` stroke-linecap="round" stroke-linejoin="round"${cls}${label}>${icon.body}</svg>`
  );
}

// The only kebab-case SVG attributes this module ever emits. Rewriting exactly
// these (rather than every hyphenated token) keeps path data untouched.
const JSX_ATTRS: [RegExp, string][] = [
  [/\bstroke-width=/g, "strokeWidth="],
  [/\bstroke-linecap=/g, "strokeLinecap="],
  [/\bstroke-linejoin=/g, "strokeLinejoin="],
  [/\bfill-rule=/g, "fillRule="],
  [/\bclip-rule=/g, "clipRule="],
  [/\bstop-color=/g, "stopColor="],
  [/\baria-hidden=/g, "aria-hidden="],
  [/\bclass=/g, "className="],
];

/** The same markup with JSX-safe attribute names — ready to drop into a .tsx file. */
export function toJsx(svg: string): string {
  return JSX_ATTRS.reduce((acc, [re, to]) => acc.replace(re, to), svg);
}

export function iconJsx(id: string, opts: IconRenderOptions = {}): string | null {
  const svg = iconSvg(id, opts);
  return svg === null ? null : toJsx(svg);
}

/**
 * `data:` URI form, for CSS `background-image` / `<img src>`. Allowed by the
 * sandbox CSP (`img-src 'self' data:`). Note that `currentColor` does NOT
 * resolve inside a data URI — pass an explicit `color`.
 */
export function iconDataUri(id: string, opts: IconRenderOptions = {}): string | null {
  const svg = iconSvg(id, { color: "#000000", ...opts });
  if (svg === null) return null;
  return `data:image/svg+xml,${encodeURIComponent(svg).replace(/'/g, "%27")}`;
}

/** All categories present, in declaration order, with their icon counts. */
export function iconCategories(): { category: IconCategory; count: number }[] {
  const counts = new Map<IconCategory, number>();
  for (const icon of ICONS) counts.set(icon.category, (counts.get(icon.category) ?? 0) + 1);
  return Array.from(counts, ([category, count]) => ({ category, count }));
}

