import { writeFileSync } from "node:fs";
import {
  BACKDROPS,
  SPOTS,
  MARKS,
  EMPTY_STATES,
  backdropSvg,
  spotSvg,
  markSvg,
  emptyStateSvg,
} from "../../../../../kodely-prod/lib/assets/illustrations.ts";

const esc = (s) => s.replace(/</g, "&lt;");

let html = `<!doctype html><meta charset="utf-8"><style>
body{font:14px system-ui;margin:0;background:#fff;color:#0f172a}
h2{padding:18px 24px 6px;margin:0;border-top:1px solid #e2e8f0}
.grid{display:flex;flex-wrap:wrap;gap:14px;padding:12px 24px}
.card{border:1px solid #e2e8f0;border-radius:10px;padding:8px;text-align:center;background:#fff}
.card .lbl{font-size:11px;color:#64748b;margin-top:6px}
.hero{width:320px;height:170px;position:relative;overflow:hidden;border-radius:8px;background:#f1f5f9;color:#4338ca}
.hero.dark{background:#0b1120;color:#a5b4fc}
.hero svg{position:absolute;inset:0}
.spot{color:#4338ca}
.dark-strip{background:#0b1120;color:#c7d2fe}
.dark-strip .card{background:#0b1120;border-color:#1e293b}
.mark{color:#e11d48}
</style><body>`;

html += `<h2>Hero backdrops (light) — ${BACKDROPS.length}</h2><div class="grid">`;
for (const b of BACKDROPS) {
  html += `<div class="card"><div class="hero">${backdropSvg(b.id)}</div><div class="lbl">backdrop:${b.id}</div></div>`;
}
html += `</div>`;

html += `<h2>Hero backdrops (dark) + a second seed</h2><div class="grid dark-strip">`;
for (const b of BACKDROPS) {
  html += `<div class="card"><div class="hero dark">${backdropSvg(b.id, { seed: b.id + "-2" })}</div><div class="lbl">${b.id} seed 2</div></div>`;
}
html += `</div>`;

html += `<h2>Spot illustrations — ${SPOTS.length}</h2><div class="grid">`;
for (const s of SPOTS) {
  html += `<div class="card spot">${spotSvg(s.id, { size: 130 })}<div class="lbl">${s.id}</div></div>`;
}
html += `</div>`;

html += `<h2>Spot illustrations on dark, accent off</h2><div class="grid dark-strip">`;
for (const s of SPOTS) {
  html += `<div class="card">${spotSvg(s.id, { size: 110, accent: false })}<div class="lbl">${s.id}</div></div>`;
}
html += `</div>`;

html += `<h2>Decorative marks — ${MARKS.length}</h2><div class="grid">`;
for (const m of MARKS) {
  html += `<div class="card mark">${markSvg(m.id, { width: 200 })}<div class="lbl">${m.id}</div></div>`;
}
html += `</div>`;

html += `<h2>Marks in context</h2><div class="grid"><div class="card" style="width:100%;text-align:left;font-size:30px;line-height:2.2">
<span style="position:relative;display:inline-block">Beautiful<span style="position:absolute;bottom:-8px;left:0;width:100%;color:#e11d48">${markSvg("underline-swash")}</span></span>
&nbsp;&nbsp;<span style="position:relative;display:inline-block;padding:0 6px"><span style="position:absolute;inset:0;color:#facc15;z-index:-1">${markSvg("highlight")}</span>highlighted</span>
&nbsp;&nbsp;<span style="position:relative;display:inline-block;padding:0 18px">circled<span style="position:absolute;inset:-6px -2px;color:#e11d48">${markSvg("circle-emphasis")}</span></span>
&nbsp;&nbsp;<span style="color:#64748b;display:inline-block;width:70px;vertical-align:middle">${markSvg("arrow-curve")}</span>
&nbsp;<span style="color:#94a3b8;display:inline-block;width:60px;vertical-align:middle">${markSvg("quote-marks")}</span>
</div></div>`;

html += `<h2>Empty states — ${EMPTY_STATES.length}</h2><div class="grid">`;
for (const e of EMPTY_STATES) {
  html += `<div class="card" style="color:#64748b;width:220px">${emptyStateSvg(e.id, { size: 190 })}<div class="lbl"><b>${e.caption}</b><br>${e.id}</div></div>`;
}
html += `</div>`;

html += `<h2>Empty states on dark</h2><div class="grid dark-strip">`;
for (const e of EMPTY_STATES) {
  html += `<div class="card" style="color:#94a3b8;width:190px">${emptyStateSvg(e.id, { size: 160 })}<div class="lbl">${e.id}</div></div>`;
}
html += `</div>`;

html += `</body>`;
writeFileSync(new URL("./gallery.html", import.meta.url), html);

// Size report
const sizes = [];
for (const b of BACKDROPS) sizes.push(["backdrop:" + b.id, backdropSvg(b.id).length]);
for (const s of SPOTS) sizes.push(["illustration:" + s.id, spotSvg(s.id).length]);
for (const m of MARKS) sizes.push(["mark:" + m.id, markSvg(m.id).length]);
for (const e of EMPTY_STATES) sizes.push(["empty-state:" + e.id, emptyStateSvg(e.id).length]);
sizes.sort((a, b) => b[1] - a[1]);
console.log(sizes.map(([k, v]) => `${String(v).padStart(5)}  ${k}`).join("\n"));
console.log("entries:", sizes.length, "total emitted bytes:", sizes.reduce((a, b) => a + b[1], 0));

