import { findAssets, listAssets, assetCatalogSummary } from "file:///C:/Users/edmem/kodely-prod/lib/assets/index.ts";

const queries = [
  "hero background",
  "hero backdrop",
  "abstract shapes behind headline",
  "empty state",
  "no items yet",
  "nothing found",
  "coffee illustration",
  "shop illustration",
  "storefront",
  "underline squiggle",
  "highlight a word",
  "arrow pointing at button",
  "quote marks testimonial",
  "sparkle",
  "plant drawing",
  "delivery van picture",
  "image placeholder",
  "no results",
  "picture for a feature",
  "decorative squiggle under heading",
  "confetti background",
  "topographic background",
  "contour lines",
  "blob background",
  "coffee shop",
  "american flag",
  "wave divider",
  "sunset gradient",
];
for (const q of queries) {
  const r = findAssets(q, { limit: 3 });
  console.log(`${q.padEnd(34)} -> ${r.map((m) => `${m.id}(${m.score})`).join(", ") || "NOTHING"}`);
}

console.log("\nsummary:", JSON.stringify(assetCatalogSummary().byKind));
console.log("total:", assetCatalogSummary().total);

// CSP + JSX safety over the new kinds
const bad = [];
for (const m of listAssets()) {
  if (!["backdrop", "illustration", "mark", "empty-state"].includes(m.kind)) continue;
  if (/(?:src|href)\s*=\s*["']https?:/i.test(m.source)) bad.push([m.id, "remote host"]);
  if (/\sstroke-|\sfill-|\sclass=|\sstop-/.test(m.source)) bad.push([m.id, "kebab attr in jsx source"]);
  for (const [k, v] of Object.entries(m.variants ?? {})) {
    if (/^data:/.test(v) && /currentColor/.test(v)) bad.push([m.id, `${k}: currentColor in data uri`]);
  }
  // balanced tags, rough check
  const open = (m.source.match(/<svg/g) ?? []).length;
  const close = (m.source.match(/<\/svg>/g) ?? []).length;
  if (open !== 1 || close !== 1) bad.push([m.id, "svg tag count"]);
}
console.log("\nproblems:", bad.length ? bad : "none");

// determinism
const a = listAssets("backdrop").map((m) => m.source).join("");
const b = listAssets("backdrop").map((m) => m.source).join("");
console.log("backdrops deterministic:", a === b);

