window.__shot = async (labels, cw, ch, cols, cell, bg) => {
  const cards = [...document.querySelectorAll('.card')].filter(c => labels.some(l => (c.querySelector('.lbl')?.textContent||'').trim().startsWith(l)));
  const cv = document.createElement('canvas'); cv.width = cw; cv.height = ch;
  const ctx = cv.getContext('2d'); ctx.fillStyle = bg; ctx.fillRect(0,0,cw,ch);
  let i = 0;
  for (const card of cards) {
    const svg = card.querySelector('svg'); if (!svg) continue;
    const clone = svg.cloneNode(true);
    const vb = (clone.getAttribute('viewBox')||'0 0 100 100').split(' ').map(Number);
    clone.setAttribute('width', vb[2]); clone.setAttribute('height', vb[3]);
    clone.setAttribute('color', getComputedStyle(svg).color);
    clone.setAttribute('style', 'color:' + getComputedStyle(svg).color);
    const s = new XMLSerializer().serializeToString(clone);
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(s); });
    const x = (i % cols) * cell, y = Math.floor(i / cols) * cell;
    const sc = Math.min(cell / img.width, cell / img.height);
    ctx.drawImage(img, x + (cell - img.width*sc)/2, y + (cell - img.height*sc)/2, img.width*sc, img.height*sc);
    i++;
  }
  return cv.toDataURL('image/png');
};
